def backfill_receipt_lines(apps, schema_editor):
    """Existing receipt lines only ever recorded accepted stock.

    Legacy semantics: quantity_received was the accepted arrival and
    rejected/damaged were informational notes. Backfill the explicit
    accepted count from it; free-text notes are never parsed.
    """
    GoodsReceiptItem = apps.get_model("procurement", "GoodsReceiptItem")
    for line in GoodsReceiptItem.objects.all().iterator():
        rejected = line.quantity_rejected or 0
        damaged = line.quantity_damaged or 0
        line.accepted_quantity = max(
            0, (line.quantity_received or 0) - rejected - damaged)
        if rejected and damaged:
            line.discrepancy_status = "mixed"
        elif rejected:
            line.discrepancy_status = "rejected"
        elif damaged:
            line.discrepancy_status = "damaged"
        line.save(update_fields=["accepted_quantity", "discrepancy_status"])


